import {speakerKey,speakerNames,displayTitle,isPause,upcoming} from './experience.js';
import {routeDay,optionsInGap,keepActivity,timetable,hm} from './timeline.js';
import {STORAGE_KEY,minutes,roomKey,emptyRules,owns,decision,selected,setRule,groupState,overlap,conflicts,eventClock,isLive,sortActivities,filterActivities,loadState,validateData} from './domain.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatDay=(d,short=false)=>new Intl.DateTimeFormat('es-CL',{weekday:short?'short':'long',day:'numeric',month:short?undefined:'long',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
let nowMode='now',searchOpen=false;
let profiles=[],data,lookup,state,readOnly=false,tab='now',day,query='',room='',level='',aux=true,layout='time',exploring=false,exploreDate,exploreTime='09:00',conflictOnly=false,dialogContext=null,undo=null,toastTimer,waitingWorker;
const opened=new Set(),scrolls={};let conflictInfo={pairs:[],ids:new Set(),unknown:[]};
const badge=l=>`<span class="badge level${l}" title="Nivel ${l}" aria-label="Nivel ${l}">${l}</span>`;
const levels=a=>a.levels.length?a.levels.map(badge).join(''):'';
const timeRange=a=>a.start&&a.end?`${a.start}–${a.end}`:'Horario no informado';
const clock=()=>exploring?{date:exploreDate,time:exploreTime}:eventClock();
function showToast(message,canUndo=false){clearTimeout(toastTimer);$('#toast').hidden=false;$('#toast').innerHTML=esc(message)+(canUndo?' <button data-action="undo">Deshacer</button>':'');toastTimer=setTimeout(()=>$('#toast').hidden=true,canUndo?9000:6500);}
function save(){if(readOnly){showToast('Los cambios se mantienen solo en esta sesión. La ruta guardada no se ha sobrescrito.');return false;}try{state.dataVersion=data.meta.version;state.signatures=Object.fromEntries(data.activities.filter(a=>selected(a,state.rules)).map(a=>[a.id,`${a.date}|${a.start}|${a.end}|${a.roomId}`]));localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{showToast('No se pudo guardar. Conserva esta pestaña abierta; tu ruta está solo en esta sesión.');return false;}}
function mutate(fn,message){const priorPairs=new Set(conflicts(data.activities,state.rules).pairs.map(p=>[p.a,p.b].sort().join('|')));undo=structuredClone(state.rules);state.rules=fn(state.rules);const saved=save();render();if(dialogContext)renderDialog();const newPairs=conflictInfo.pairs.filter(p=>!priorPairs.has([p.a,p.b].sort().join('|')));if(newPairs.length){const pair=newPairs[0],a=lookup.activities[pair.a],b=lookup.activities[pair.b];showToast(`Conflicto: ${a.start} · S${roomNumber(lookup.rooms[a.roomId])} coincide con ${b.start} · S${roomNumber(lookup.rooms[b.roomId])}. Se conservan ambas elecciones.`,true);const review=document.createElement('button');review.dataset.action='conflicts';review.textContent='Revisar';$('#toast').append(review);}else if(message&&saved)showToast(message,true);}
function speakerButton(a){return speakerNames(a.speaker).map(name=>`<button class="speaker-link" data-speaker="${a.id}" data-speaker-name="${esc(name)}">${esc(name)}</button>`).join('<span class="speaker-separator"> · </span>');}
function compactRow(a){const r=lookup.rooms[a.roomId],sel=selected(a,state.rules),module=lookup.blocks[a.blockId].title.replace(/ABDOMEN & PELVIS/gi,'Abd. y pelvis').replace(/MÓDULO/gi,'').trim();return `<article class="dense-talk ${sel?'selected':''}" data-activity="${a.id}"><span class="dense-room" aria-label="Salón ${roomNumber(r)}">${roomNumber(r)}</span><button class="dense-text" data-detail="${a.id}" aria-label="${esc(displayTitle(a))}. ${esc(a.speaker)}. ${timeRange(a)}"><span class="dense-title">${esc(displayTitle(a))}</span><span class="dense-meta">${esc([a.speaker,module].filter(Boolean).join(' · '))}</span></button><span class="dense-levels">${levels(a)}</span>${pick(a)}${conflictInfo.ids.has(a.id)?'<span class="dense-conflict" aria-label="Conflicto de horario" title="Conflicto de horario">!</span>':''}</article>`;}
function denseRows(items){const groups=new Map(),out=[];for(const a of [...items].sort((a,b)=>Number(roomNumber(lookup.rooms[a.roomId]))-Number(roomNumber(lookup.rooms[b.roomId])))){if(isPause(a)||/ceremonia|inaugura|clausura/i.test(a.title)){const label=a.title.replace(/coffee\s*break|pausa caf[eé]/gi,'Café'),key=label+'|'+a.start+'|'+a.end;if(!groups.has(key)){const g={label,items:[]};groups.set(key,g);out.push(g);}groups.get(key).items.push(a);}else out.push(a);}return '<div class="dense-card">'+out.map(x=>x.items?`<button class="dense-pause" data-collection="${x.items.map(a=>a.id).join(',')}"><span>${/caf[eé]/i.test(x.label)?'☕ ':''}${esc(x.label)} ${timeRange(x.items[0])}</span><small>${x.items.length>1?x.items.length+' salones':'S'+roomNumber(lookup.rooms[x.items[0].roomId])} ›</small></button>`:compactRow(x)).join('')+'</div>';}
function denseSection(title,items){return `<section class="dense-section"><h2>${esc(title)}</h2>${denseRows(items)}</section>`;}
function timeList(visible){if(!visible.length)return empty('Sin resultados','Limpia los filtros o cambia de día.',false);return '<div class="time-list">'+[...new Set(visible.map(a=>a.start??'Sin horario'))].sort().map(t=>denseSection(t,visible.filter(a=>(a.start??'Sin horario')===t))).join('')+'</div>';}
function nextBlock(c){const future=data.activities.filter(a=>a.start&&(a.date>c.date||a.date===c.date&&a.start>c.time)).sort(sortActivities),first=future[0];return first?future.filter(a=>a.date===first.date&&a.start===first.start):[];}
function publishedTimes(date){return [...new Set(data.activities.filter(a=>a.date===date&&a.start).map(a=>a.start))].sort();}

function row(a,{showRoom=true,live=false}={}){const d=decision(a,state.rules),c=conflictInfo.ids.has(a.id);return `<article class="activity ${d.selected?'selected':''} ${c?'conflicted':''} ${isPause(a)?'pause-row':a.auxiliary?'auxiliary':''}" data-activity="${a.id}"><div class="timecell">${esc(a.start??'—')}<span>${esc(a.end??'Por informar')}</span></div><div><button class="activity-title" data-detail="${a.id}">${esc(displayTitle(a))}</button><div class="activity-meta">${showRoom?`${esc(lookup.rooms[a.roomId].name)}${a.speaker?' · ':''}`:''}${speakerButton(a)}</div><div class="activity-tags">${live?'<span class="badge live">Ahora</span>':''}${levels(a)}${c?'<span class="badge conflict">Coincide con tu ruta</span>':''}${!a.start?'<span class="badge">Horario pendiente</span>':''}</div>${d.source==='individual'?`<div class="exception">${d.selected?'Elección individual':'Excluida de mi ruta'}</div>`:d.selected?`<div class="exception">Incluida por ${d.source==='block'?'bloque':'sala'}</div>`:''}</div><button class="pick" data-pick="${a.id}" aria-pressed="${d.selected}" aria-label="${d.selected?'Quitar de':'Agregar a'} mi ruta: ${esc(displayTitle(a))}">${d.selected?'✓':'+'}</button></article>`;}
const roomNumber=r=>r.name.match(/Salón (\d+)/)?.[1]??'–';
const roomName=r=>r.name.split(' · ').at(-1);
const pick=a=>`<button class="pick" data-pick="${a.id}" aria-pressed="${selected(a,state.rules)}" aria-label="${selected(a,state.rules)?'Quitar de':'Agregar a'} mi ruta: ${esc(displayTitle(a))}">${selected(a,state.rules)?'✓':'+'}</button>`;
function groupControl(scope,key,items){const g=groupState(items,state.rules);return `<button class="groupcheck ${g.state}" data-group="${scope}" data-key="${key}" aria-label="Elegir ${scope==='room'?'sala':'bloque'}: ${g.count} de ${g.total} seleccionadas" title="${g.count}/${g.total} en ruta; configurar grupo">${g.state==='all'?'✓':g.state==='mixed'?'−':'+'}</button>`;}
function dayButtons(){return `<div class="daybar" aria-label="Día del programa">${data.meta.dates.map(d=>`<button class="daybutton ${day===d?'active':''}" data-day="${d}" aria-pressed="${day===d}">${formatDay(d,true)}</button>`).join('')}</div>`;}
function toolbar(){
 if(tab==='route')return dayButtons()+`<div class="route-tools"><button class="textbutton" data-action="clear-dialog">Restablecer ruta</button>${exploring?'<span class="badge">Modo exploración</span>':''}</div>`;
 const rooms=data.rooms.filter(r=>data.activities.some(a=>a.roomId===r.id&&a.date===(tab==='now'?clock().date:day)));
 const active=query||room||level||!aux;
 const filters=`<details class="filterpanel" ${active?'open':''}><summary>Buscar${active?' · filtros activos':''}</summary><div class="filters"><label class="searchbox"><span class="sr-only">Buscar charla, ponente o tema</span><input type="search" id="search" placeholder="Charla, ponente o tema" value="${esc(query)}"></label><select class="filterselect" id="roomFilter" aria-label="Filtrar por sala"><option value="">Todas las salas</option>${rooms.map(r=>`<option value="${r.id}" ${room===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><select class="filterselect" id="levelFilter" aria-label="Filtrar por nivel"><option value="">Todos los niveles</option>${[1,2,3].map(l=>`<option value="${l}" ${level===String(l)?'selected':''}>Nivel ${l}</option>`).join('')}<option value="none" ${level==='none'?'selected':''}>Sin nivel informado</option></select></div><div class="optionsbar"><label class="switchlabel"><input type="checkbox" id="auxToggle" ${aux?'checked':''}> Pausas y otras actividades</label><button class="textbutton" data-action="clear-filters">Limpiar filtros</button></div></details>`;
 const chips=`<div class="levelchips" aria-label="Filtrar por nivel">${[1,2,3].map(l=>`<button class="levelchip ${level===String(l)?'active':''}" data-level="${l}" aria-pressed="${level===String(l)}" aria-label="Nivel ${l}">${badge(l)}</button>`).join('')}</div>`;
 const c=clock();
 $('#headerSearch').innerHTML=filters;$('#headerSearch').hidden=!searchOpen;$('#searchButton').setAttribute('aria-expanded',String(searchOpen));$('#searchButton').classList.toggle('has-filters',Boolean(active));
 return tab==='now'?`<div class="now-chips"><button data-now-mode="now" aria-pressed="${nowMode==='now'}">Ahora</button><button data-now-mode="next" aria-pressed="${nowMode==='next'}">Siguiente</button><button data-now-mode="custom" aria-pressed="${nowMode==='custom'}">Otra hora ▾</button>${exploring?`<small>Consulta · ${formatDay(c.date,true)} ${c.time}</small>`:''}</div>`:`<div class="program-controls"><div class="segmented"><button data-layout="time" class="${layout==='time'?'active':''}" aria-pressed="${layout==='time'}">Por horario</button><button data-layout="room" class="${layout==='room'?'active':''}" aria-pressed="${layout==='room'}">Por salón</button><button data-layout="grid" class="desktop-grid ${layout==='grid'?'active':''}" aria-pressed="${layout==='grid'}">Tabla</button></div></div><div class="day-level-row">${dayButtons()}${chips}</div>`;
}
function empty(title,message,action=true){return `<div class="empty"><div class="emptyicon" aria-hidden="true">◷</div><h2>${esc(title)}</h2><p>${esc(message)}</p>${action?'<button class="primary" data-tab="program">Explorar el programa</button>':''}</div>`;}
function renderProgram(){
 const visible=filterActivities(data.activities,{day,room,level,q:query,aux},lookup),matches=new Set(visible.map(a=>a.id)),daily=data.activities.filter(a=>a.date===day),rooms=data.rooms.filter(r=>daily.some(a=>a.roomId===r.id));
 if(layout==='time'||layout==='grid'&&innerWidth<768)return timeList(visible);
 if(layout==='grid'){
 const grid=timetable(daily),c=clock(),columnOf=id=>2+rooms.slice(0,rooms.findIndex(r=>r.id===id)).reduce((n,r)=>n+(grid.roomLanes[r.id]||1),0),columns=rooms.reduce((n,r)=>n+(grid.roomLanes[r.id]||1),0);let html=`<p class="grid-hint">${visible.length} coincidencias · Desliza la tabla para comparar salones. Toca un título para leerlo completo.</p><div class="schedule-scroll" data-date="${day}" tabindex="0" role="region" aria-label="Programa por horario y salón"><div class="schedule" style="--columns:${columns};--rows:${grid.times.length-1}"><div class="schedule-corner">Hora</div>`;
 html+=rooms.map((r,i)=>{const items=daily.filter(a=>a.roomId===r.id),g=groupState(items,state.rules);return `<div class="schedule-room" style="grid-column:${columnOf(r.id)} / span ${grid.roomLanes[r.id]||1}"><span class="big-number">${roomNumber(r)}</span><div><strong>${esc(roomName(r))}</strong><small>${g.count}/${g.total} en ruta</small></div>${groupControl('room',r.id,items)}</div>`}).join('');
 html+=grid.times.slice(0,-1).map((t,i)=>`<div class="schedule-time ${c.date===day&&t<=c.time&&grid.times[i+1]>c.time?'current':''}" style="grid-row:${i+2}">${t}</div>`).join('');
 html+=grid.items.map(({activity:a,start,end,lane})=>{const sel=selected(a,state.rules),ex=owns(state.rules.activities,a.id)&&!sel,block=lookup.blocks[a.blockId],first=daily.filter(b=>b.blockId===a.blockId).sort(sortActivities)[0]?.id===a.id;return `<article class="schedule-cell ${sel?'selected':''} ${ex?'excluded':''} ${!matches.has(a.id)?'dimmed':''} ${isPause(a)?'pause-row':a.auxiliary?'auxiliary':''}" data-grid-activity="${a.id}" style="grid-column:${columnOf(a.roomId)+lane};grid-row:${start+2}/${end+2}">${first?`<div class="module-band"><span title="${esc(block.title)}">${esc(block.title)}</span>${groupControl('block',a.blockId,daily.filter(b=>b.blockId===a.blockId))}</div>`:''}<button class="cell-title" data-detail="${a.id}">${esc(displayTitle(a))}</button>${speakerButton(a)}<small class="cell-range">${timeRange(a)}</small><div class="cell-bottom"><span>${levels(a)}${ex?'<span class="excluded-label">Excluida</span>':''}${conflictInfo.ids.has(a.id)?'<span class="badge conflict">Conflicto</span>':''}</span>${pick(a)}</div></article>`}).join('');
 html+='</div></div>';if(grid.unknown.length)html+='<h2 class="route-day">Horario no informado</h2>'+grid.unknown.filter(a=>matches.has(a.id)).map(a=>row(a)).join('');return html;
 }
 const activeRoom=rooms.find(r=>r.id===room)||rooms[0];if(!activeRoom)return empty('Sin actividades','No hay actividades para este día.',false);
 let html=`<div class="room-tabs" aria-label="Salones">${rooms.map(r=>`<button data-room="${r.id}" class="${r.id===activeRoom.id?'active':''}" aria-pressed="${r.id===activeRoom.id}"><strong>${roomNumber(r)}</strong><span>${esc(roomName(r))}</span></button>`).join('')}</div>`;
 const all=daily.filter(a=>a.roomId===activeRoom.id),gs=groupState(all,state.rules);html+=`<div class="room-header"><h2>${esc(activeRoom.name)}</h2><span>${gs.count} de ${gs.total}</span>${groupControl('room',activeRoom.id,all)}</div><div class="block-legend"><span>▌ Completo</span><span>▌ Parcial</span><small>Toca la barra para elegir el bloque</small></div>`;
 const bs=data.blocks.filter(b=>b.date===day&&b.roomId===activeRoom.id);let shown=0;
 for(const b of bs){const items=all.filter(a=>a.blockId===b.id),rows=items.filter(a=>matches.has(a.id)),g=groupState(items,state.rules);if(!rows.length)continue;shown+=rows.length;html+=`<section class="salon-block ${g.state}"><button class="block-rail" data-group="block" data-key="${b.id}" aria-label="Elegir bloque ${esc(displayTitle(b))}, ${g.count} de ${g.total} en ruta"><span>${g.state==='all'?'✓':g.state==='mixed'?'−':'+'}</span><i></i></button><div class="block-content"><h3>${esc(displayTitle(b))}</h3><p>${esc(b.start??'Sin hora')}${b.end?'–'+b.end:''} · ${g.count}/${g.total} en tu ruta</p>${rows.sort(sortActivities).map(a=>row(a,{showRoom:false})).join('')}</div></section>`;}
 return html+(shown?'':empty('Sin resultados en este salón','Prueba otro salón o limpia los filtros.',false));
}
function renderNow(){const c=clock(),allLive=data.activities.filter(a=>isLive(a,c)),next=nextBlock(c),visible=items=>filterActivities(items,{room,level,q:query,aux},lookup),live=visible(allLive),future=visible(next),personal=[...allLive,...next].filter(a=>selected(a,state.rules));let html=personal.length?'<div class="dense-personal" aria-label="Mi ruta en este bloque">'+personal.map(a=>`<button data-detail="${a.id}"><b>Mi ruta · ${isLive(a,c)?'en curso':'siguiente'} · S${roomNumber(lookup.rooms[a.roomId])}</b><span>${esc(displayTitle(a))}</span></button>`).join('')+'</div>':'';
 if(allLive.length){const starts=new Set(allLive.map(a=>a.start)),ends=new Set(allLive.map(a=>a.end)),range=starts.size===1&&ends.size===1?timeRange(allLive[0]):c.time;html+=denseSection((exploring?'EN ESTE HORARIO':'AHORA')+' · '+range,live);if(!live.length)html+='<p class="dense-note">No hay coincidencias con tus filtros en este bloque.</p>';if(next.length)html+=denseSection('A CONTINUACIÓN · '+(next[0].date===c.date?'':formatDay(next[0].date,true)+' ')+next[0].start,future);}
 else if(next.length){const first=next[0],tomorrow=new Date(c.date+'T12:00:00Z');tomorrow.setUTCDate(tomorrow.getUTCDate()+1);const when=first.date===c.date?'hoy':first.date===tomorrow.toISOString().slice(0,10)?'mañana':formatDay(first.date);html+='<p class="dense-note">El congreso continúa '+when+' a las '+first.start+'.</p>'+denseSection('PRÓXIMO BLOQUE · '+formatDay(first.date,true)+' '+first.start,future);}
 else html+=empty('El congreso finalizó','Puedes consultar el programa y tu ruta guardada.');return html;}

function renderRoute(){
 const route=routeDay(data.activities,state.rules,day);if(!route.chosen.length)return empty('Tu ruta empieza con una elección','No hay actividades elegidas para este día. Puedes elegir otro día o agregar una sala, un bloque o una charla.');
 const pairs=conflictInfo.pairs.filter(p=>lookup.activities[p.a].date===day);let html=`<div class="route-stats"><strong>${route.chosen.length} actividades · ${route.changes} cambios${route.unknown.length?'':' · '+route.freeMinutes+' min libres'}</strong>${pairs.length?`<button class="conflict-pill" data-action="conflicts">${pairs.length} ${pairs.length===1?'conflicto':'conflictos'}</button>`:''}</div>`;
 if(pairs.length)html+='<p class="conflict-note">Se conservan todas tus elecciones. «Quedarme» excluye solo las que coinciden con esa actividad y permite deshacer.</p>';
 html+='<p class="scale-note">Intervalos breves ampliados para facilitar la lectura.</p><div class="route-timeline">';const c=clock();
 for(const seg of route.segments){const live=c.date===day&&minutes(c.time)>=seg.start&&minutes(c.time)<seg.end,past=c.date>day||c.date===day&&minutes(c.time)>=seg.end,options=seg.kind==='free'?optionsInGap(data.activities,day,seg.start,seg.end):[],height=Math.max(seg.kind==='free'?72:108,(seg.end-seg.start)*3);
 html+=`<section class="route-segment ${seg.kind} ${past?'past':''} ${live?'live-segment':''}" style="--segment-height:${height}px"><div class="route-axis">${hm(seg.start)}</div><div class="segment-content">${seg.change?`<button class="change-chip" data-map="${seg.items[0].roomId}">Cambio a S${roomNumber(lookup.rooms[seg.items[0].roomId])}</button>`:''}`;
 if(seg.kind==='free')html+=`<button class="free-slot" data-gap="${seg.start},${seg.end}"><strong>${seg.end-seg.start} min libres</strong><span>${hm(seg.start)}–${hm(seg.end)}</span><b>Ver ${options.length} opciones</b></button>`;
 else html+=`<div class="route-cards">${seg.items.map(a=>`<article class="route-card activity ${isPause(a)?'pause-row':''} ${conflictInfo.ids.has(a.id)?'conflicted':''}" data-activity="${a.id}"><div class="route-room">${roomNumber(lookup.rooms[a.roomId])}</div><div class="route-card-text"><button class="activity-title" data-detail="${a.id}">${esc(displayTitle(a))}</button><small>${timeRange(a)} · ${esc(roomName(lookup.rooms[a.roomId]))}</small>${seg.kind==='conflict'?`<button class="keep-button" data-keep="${a.id}">Quedarme</button>`:''}</div>${seg.kind==='conflict'?'':pick(a)}</article>`).join('')}</div>`;
 html+=`</div>${live?`<div class="now-line" style="top:${Math.max(0,Math.min(100,(minutes(c.time)-seg.start)/(seg.end-seg.start)*100))}%"><span>${c.time}</span></div>`:''}</section>`;
 }
 html+='</div>';if(route.unknown.length)html+='<div class="notice">Hay actividades sin horario. No se pueden asegurar tiempos libres ni comprobar todos los conflictos.</div>'+route.unknown.map(a=>row(a)).join('');return html;
}
function render(onlyContent=false){if(!data)return;const oldGrid=$('.schedule-scroll'),gridPosition=oldGrid&&oldGrid.dataset.date===day?{left:oldGrid.scrollLeft,top:oldGrid.scrollTop}:null;conflictInfo=conflicts(data.activities,state.rules);const total=data.activities.filter(a=>selected(a,state.rules)).length;if(!conflictInfo.pairs.length)conflictOnly=false;
 const c=clock();document.body.dataset.view=tab;document.body.dataset.exploring=String(exploring);$('#headerClock').textContent=c.time;$('#headerDate').textContent=formatDay(c.date,true)+' oct';$('#sectionLabel').textContent={now:'Tablero',program:'Programa',route:'Mi Ruta'}[tab];$('#routeCount').textContent=total;$('#routeSummary').innerHTML=`<strong>${total}</strong> en tu ruta${conflictInfo.pairs.length?`<br><span>${conflictInfo.pairs.length} coincidencias por revisar</span>`:''}`;
 document.querySelectorAll('#navigation [data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 $('#viewTitle').textContent={now:'¿Qué está pasando?',program:'Programa',route:'Mi Ruta'}[tab];$('#viewSubtitle').textContent={now:'Lo que ocurre ahora, sala por sala.',program:'Todas las salas. Tu próxima elección.',route:'Tus elecciones, en orden. A tu ritmo.'}[tab];if(!onlyContent)$('#toolbar').innerHTML=toolbar();
 $('#content').innerHTML=(data.meta.auditStatus!=='reviewed'?'<div class="notice">Programa en revisión. Consulta la fuente de cada actividad para confirmar los detalles.</div>':'')+(tab==='now'?renderNow():tab==='program'?renderProgram():renderRoute());
 const newGrid=$('.schedule-scroll');if(newGrid){if(gridPosition){newGrid.scrollLeft=gridPosition.left;newGrid.scrollTop=gridPosition.top;}else{const current=newGrid.querySelector('.schedule-time.current');if(current)newGrid.scrollTop=current.offsetTop-76;}}
 document.querySelectorAll('details[data-block]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)opened.add(d.dataset.block);else opened.delete(d.dataset.block)}));
}
function setTab(next){if(!['now','program','route'].includes(next))return;if($('#detail').open)$('#detail').close();scrolls[tab]=window.scrollY;tab=next;if(next==='route'&&exploring)day=exploreDate;render();window.scrollTo({top:scrolls[tab]??0,behavior:'instant'});}
function openDialog(context){dialogContext=context;renderDialog();if(!$('#detail').open)$('#detail').showModal();}
function groupActivities(ctx){return data.activities.filter(a=>ctx.scope==='block'?a.blockId===ctx.key:a.roomId===ctx.key&&(ctx.allDays||a.date===ctx.date));}
function mapView(roomId){const r=lookup.rooms[roomId],n=Number(roomNumber(r)),page=n>=6?6:5;return `<div class="map-panel"><strong>${esc(r.name)} · ${page===6?'Planta alta':'Planta baja'}</strong><p>Plano del programa original, página ${page}. No se estima tu ubicación ni el tiempo de traslado.</p><a href="./plano-${page}.webp" target="_blank" rel="noopener" aria-label="Ampliar plano de ${page===6?'planta alta':'planta baja'}"><img src="./plano-${page}.webp" alt="Plano oficial del recinto: ${page===6?'Manquehue, Polo y Parque en planta alta':'Escultura, Vitacura, Cordillera y Planeadores en planta baja'}. Destino: ${esc(r.name)}."></a><a href="./programa-2026.pdf#page=${page}" target="_blank" rel="noopener">Consultar plano en el PDF</a></div>`;}
function renderDialog(){
 const ctx=dialogContext;if(!ctx)return;let title='',html='';
 if(ctx.kind==='time-selector'){title='Consultar otro horario';const date=ctx.date??exploreDate;html=`<div class="time-selector"><label>Día<select id="blockDate">${data.meta.dates.map(d=>`<option value="${d}" ${date===d?'selected':''}>${formatDay(d)}</option>`).join('')}</select></label><label>Bloque<select id="blockTime">${publishedTimes(date).map(t=>`<option value="${t}" ${exploreTime===t?'selected':''}>${t}</option>`).join('')}</select></label><button class="primary" data-action="apply-block">Ver bloque</button></div>`;
 }else if(ctx.kind==='collection'){title='Actividades del bloque';html=ctx.ids.map(id=>row(lookup.activities[id])).join('');
 }else if(ctx.kind==='detail'){

 const a=lookup.activities[ctx.id],d=decision(a,state.rules),r=lookup.rooms[a.roomId],alternatives=data.activities.filter(b=>overlap(a,b)).sort(sortActivities);title=r.name+' · '+timeRange(a);html=`<p class="detail-module">${esc(lookup.blocks[a.blockId].title)}</p><h3 class="detail-title">${esc(displayTitle(a))}</h3>${a.speaker?`<p class="detail-speaker">${a.speakerRole==='moderator'?'Modera: ':''}${speakerButton(a)}</p>`:''}<div class="detail-levels">${levels(a)}<span>${a.levels.length?'Nivel'+(a.levels.length>1?'es ':' ')+a.levels.join(' y '):'Sin nivel informado'}</span></div><p class="details-note">${formatDay(a.date)} · ${timeRange(a)}${d.selected?' · En mi ruta':''}</p>${a.note?`<div class="notice">${esc(a.note)}</div>`:''}<div class="detail-actions"><button class="primary ${d.selected?'on-route':''}" data-pick="${a.id}">${d.selected?'✓ En mi ruta · Quitar':'Agregar a mi ruta'}</button><button class="secondary" data-action="toggle-map">${ctx.map?'Ocultar plano':'Ver en plano'}</button></div>${owns(state.rules.activities,a.id)?`<button class="textbutton" data-inherit="${a.id}">Usar selección del grupo</button>`:''}${ctx.map?mapView(a.roomId):''}<div class="detail-section"><h3>Al mismo tiempo · ${alternatives.length} alternativas</h3>${a.start&&a.end?alternatives.map(b=>`<div class="alternative"><span class="big-number">${roomNumber(lookup.rooms[b.roomId])}</span><div><button class="activity-title" data-detail="${b.id}">${esc(displayTitle(b))}</button><div class="activity-meta">${levels(b)} ${esc(roomName(lookup.rooms[b.roomId]))} · ${timeRange(b)}</div></div>${pick(b)}</div>`).join('')||'<p class="details-note">No hay otras actividades en este intervalo.</p>':'<p class="details-note">El horario no está informado; no se pueden calcular coincidencias.</p>'}</div><div class="detail-section"><a href="./programa-2026.pdf#page=${a.source.page}" target="_blank" rel="noopener">Ver programa original · página ${a.source.page}</a><p class="details-note">${esc(a.source.document)} · Registro contrastado con el PDF${a.source.additionalPages?.length?' · También figura en páginas '+a.source.additionalPages.join(', '):''}</p></div>`;
 }else if(ctx.kind==='speaker'){
 const origin=lookup.activities[ctx.id],key=speakerKey(ctx.name??origin.speaker),matches=profiles.filter(p=>speakerKey(p.name)===key),profile=matches.length===1?matches[0]:null,others=data.activities.filter(a=>speakerNames(a.speaker).some(name=>speakerKey(name)===key)).sort(sortActivities);title=ctx.name??origin.speaker;html=`<div class="speaker-profile">${profile?.photo?`<img src="${esc(profile.photo)}" alt="${esc(profile.name)}" referrerpolicy="no-referrer" loading="lazy">`:''}<div>${profile?.position?`<p class="detail-module">${esc(profile.position)}</p>`:''}${profile?.bioExcerpt?`<blockquote>${esc(profile.bioExcerpt)}</blockquote>`:'<p class="details-note">No hay biografía verificada disponible para este nombre.</p>'}${profile?`<a href="${esc(profile.source)}" target="_blank" rel="noopener">Ficha y biografía completa · Conf.app</a>`:''}</div></div><div class="detail-section"><h3>${others.length} actividades en el programa</h3>${others.map(a=>`<p class="speaker-day">${formatDay(a.date)}</p>${row(a)}`).join('')}</div>`;
 }else if(ctx.kind==='gap'){
 title='Opciones · '+hm(ctx.start)+'–'+hm(ctx.end);const options=optionsInGap(data.activities,ctx.date,ctx.start,ctx.end);html=`<p class="details-note">${options.length} actividades caben completamente en este intervalo. ${formatDay(ctx.date)}.</p>`+options.map(a=>row(a)).join('');
 }else if(ctx.kind==='map'){
 title='Ubicación del salón';html=mapView(ctx.roomId);
 }else if(ctx.kind==='group'){
 title=ctx.scope==='room'?'Elegir una sala':'Elegir un bloque';const items=groupActivities(ctx),gs=groupState(items,state.rules),name=ctx.scope==='room'?lookup.rooms[ctx.key].name:lookup.blocks[ctx.key].title,specific=items.filter(a=>owns(state.rules.activities,a.id)).length;html=`<h3 class="detail-title">${esc(name)}</h3><p class="details-note">${ctx.allDays?'Todos los días de esta sala':formatDay(ctx.date)}</p>${ctx.scope==='room'?`<label class="switchlabel"><input type="checkbox" id="allDays" ${ctx.allDays?'checked':''}> Esta sala durante todo el congreso</label>`:''}<div class="rulebox">${items.length} actividades en el ámbito completo, incluso las ocultas por filtros.<br><strong>${gs.count} elegidas · ${specific} decisiones individuales.</strong><br>Se conservan las excepciones de charlas${ctx.scope==='room'?' y bloques':''}.</div><div class="buttonrow"><button class="primary" data-group-rule="include">Incluir ${ctx.scope==='room'?'sala':'bloque'}</button><button class="secondary" data-group-rule="exclude">Excluir ${ctx.scope==='room'?'sala':'bloque'}</button></div><button class="textbutton" data-group-rule="inherit">${ctx.scope==='block'?'Usar la selección de la sala':'Quitar la regla de la sala'}</button><div class="detail-section"><h3>Restablecer excepciones</h3><p class="details-note">Borra las decisiones individuales${ctx.scope==='room'?' y de bloques':''} de este ámbito. Las actividades volverán a seguir la regla del grupo.</p><button class="secondary" data-group-rule="reset">Restablecer excepciones del grupo</button></div>`;
 }else if(ctx.kind==='conflicts'){
 title='Coincidencias de horario';html=`<p class="details-note">Cada par comparte tiempo. Puedes conservarlo o quitar una elección.</p>${conflictInfo.pairs.map(p=>{const a=lookup.activities[p.a],b=lookup.activities[p.b];return `<div class="conflict-pair"><strong>${formatDay(a.date)} · ${p.minutes} min superpuestos</strong>${row(a)}${row(b)}</div>`}).join('')||'<p>No quedan coincidencias.</p>'}`;
 }else if(ctx.kind==='clear'){
 title='Restablecer mi ruta';html='<p class="details-note">Se borrarán todas las reglas de salas, bloques y charlas guardadas en este dispositivo. Podrás deshacerlo inmediatamente.</p><button class="primary" data-action="clear-route">Borrar selecciones y excepciones</button>';
 }else{
 title='Sobre tu agenda';html=`<h3 class="detail-title">Congreso 2.0</h3><p class="details-note">App no oficial · datos de la agenda CChR 2026. No reemplaza los avisos de la organización.</p><div class="statgrid"><div><strong>${data.activities.length}</strong><span>actividades</span></div><div><strong>${data.blocks.length}</strong><span>bloques</span></div><div><strong>${data.meta.sourcePages}</strong><span>páginas de fuente</span></div></div><h3>Datos y fuente</h3><p class="details-note">Versión ${esc(data.meta.version)}. Basada en el HTML y PDF que proporcionaste. Cada actividad enlaza su página. ${esc(data.meta.auditSummary??'Revisión de la fuente en curso.')}</p><div class="buttonrow"><a class="secondary" href="./programa-2026.pdf" target="_blank" rel="noopener">Abrir PDF</a><a class="secondary" href="./audit.html" target="_blank" rel="noopener">Ver auditoría</a><a class="secondary" href="https://congresochilenoradiologia.cl/programa/" target="_blank" rel="noopener">Sitio oficial</a></div><div class="detail-section"><h3>Instalar en tu teléfono</h3><p class="details-note"><strong>iPhone · Safari:</strong> abre Compartir y elige «Agregar a inicio».<br><strong>Android · Chrome:</strong> abre el menú y elige «Instalar app» o «Agregar a pantalla principal» cuando esté disponible.</p><p class="details-note">Tu ruta se guarda solo en este navegador y dispositivo. No se sincroniza. Borrar los datos del navegador elimina esas elecciones. Las selecciones de un archivo HTML abierto anteriormente no se trasladan entre direcciones distintas.</p><p class="details-note">${navigator.serviceWorker?.controller?'La agenda está preparada para consultas sin conexión tras su primera carga. El PDF se abre por separado.':'La disponibilidad sin conexión se prepara al cargar la app por HTTPS.'}</p><p class="details-note">Si ves un aviso de actualización, puedes aplicarla conservando tu ruta.</p></div>`;
 }
 $('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;$('#dialogBody').querySelectorAll('.speaker-profile img').forEach(img=>img.onerror=()=>{img.hidden=true;});
}
document.addEventListener('click',e=>{
 const el=e.target.closest('button');if(!el||!data)return;
 if(el.dataset.collection){openDialog({kind:'collection',ids:el.dataset.collection.split(',')});return;}
 if(el.dataset.nowMode){const mode=el.dataset.nowMode;if(mode==='custom'){openDialog({kind:'time-selector',date:exploreDate});return;}nowMode=mode;exploring=mode==='next';if(exploring){const next=nextBlock(eventClock())[0];if(!next){exploring=false;nowMode='now';showToast('No quedan bloques posteriores.');}else{exploreDate=next.date;exploreTime=next.start;}}render();return;}
 if(el.dataset.speaker){openDialog({kind:'speaker',id:el.dataset.speaker,name:el.dataset.speakerName});return;}
 if(el.dataset.upcoming){day=el.dataset.upcoming;room='';query='';level='';setTab('program');return;}
 if(el.dataset.tab){setTab(el.dataset.tab);return;}
 if(el.dataset.day){day=el.dataset.day;room='';opened.clear();render();return;}
 if(el.dataset.layout){layout=el.dataset.layout;render();return;}
 if(el.dataset.room){room=el.dataset.room;render();return;}
 if(el.dataset.level){level=level===el.dataset.level?'':el.dataset.level;render();return;}
 if(el.dataset.gap){const [start,end]=el.dataset.gap.split(',').map(Number);openDialog({kind:'gap',date:day,start,end});return;}
 if(el.dataset.keep){mutate(r=>keepActivity(data.activities,r,el.dataset.keep),'Elección conservada; se excluyeron solo sus coincidencias.');return;}
 if(el.dataset.map){openDialog({kind:'map',roomId:el.dataset.map});return;}
 if(el.dataset.pick){const a=lookup.activities[el.dataset.pick];if(a)mutate(r=>setRule(r,'activities',a.id,!selected(a,r)),selected(a,state.rules)?'Actividad excluida de tu ruta.':'Actividad agregada a tu ruta.');return;}
 if(el.dataset.inherit){mutate(r=>setRule(r,'activities',el.dataset.inherit,undefined),'La actividad vuelve a seguir su grupo.');return;}
 if(el.dataset.detail){openDialog({kind:'detail',id:el.dataset.detail});return;}
 if(el.dataset.group){openDialog({kind:'group',scope:el.dataset.group,key:el.dataset.key,date:day,allDays:false});return;}
 if(el.dataset.groupRule){const ctx=dialogContext;if(ctx?.kind!=='group')return;const mode=el.dataset.groupRule,items=groupActivities(ctx);mutate(r=>{let next=structuredClone(r);if(mode==='reset'){items.forEach(a=>{delete next.activities[a.id];if(ctx.scope==='room')delete next.blocks[a.blockId]});}else{const val=mode==='include'?true:mode==='exclude'?false:undefined,keys=ctx.scope==='block'?[ctx.key]:[...new Set(items.map(roomKey))];keys.forEach(k=>next=setRule(next,ctx.scope==='block'?'blocks':'rooms',k,val));}return next;},mode==='reset'?'Excepciones restablecidas.':'Regla actualizada; se conservaron las excepciones.');return;}
 const action=el.dataset.action;
 if(action==='apply-block'){exploreDate=$('#blockDate').value;exploreTime=$('#blockTime').value;if(!exploreTime)return;exploring=true;nowMode='custom';$('#detail').close();render();}

 if(action==='undo'&&undo){const prior=undo;undo=null;state.rules=prior;save();render();if(dialogContext)renderDialog();showToast('Cambio deshecho.');}
 if(action==='clear-filters'){query='';room='';level='';aux=true;render();}
 if(action==='explore'){exploring=!exploring;if(exploring){const real=eventClock();exploreDate=data.meta.dates.includes(real.date)?real.date:day;exploreTime=data.meta.dates.includes(real.date)?real.time:'09:00';}room='';render();}
 if(action==='go-room'){day=clock().date;room=el.dataset.key;layout='room';setTab('program');}
 if(action==='toggle-map'&&dialogContext?.kind==='detail'){dialogContext.map=!dialogContext.map;renderDialog();}
 if(action==='conflicts')openDialog({kind:'conflicts'});
 if(action==='conflict-filter'){conflictOnly=!conflictOnly;render();}
 if(action==='clear-dialog')openDialog({kind:'clear'});
 if(action==='clear-route'){mutate(()=>emptyRules(),'Ruta restablecida.');$('#detail').close();}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;render(true);}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='blockDate'){dialogContext.date=e.target.value;renderDialog();return;}if(id==='roomFilter')room=e.target.value;if(id==='levelFilter')level=e.target.value;if(id==='auxToggle')aux=e.target.checked;if(id==='exploreDate'){exploreDate=e.target.value;day=exploreDate;room='';}if(id==='exploreTime'){if(!e.target.value)return;exploreTime=e.target.value;}if(id==='allDays'&&dialogContext?.kind==='group'){dialogContext.allDays=e.target.checked;renderDialog();return;}if(['roomFilter','levelFilter','auxToggle','exploreDate','exploreTime'].includes(id))render();});
$('#searchButton').addEventListener('click',()=>{searchOpen=!searchOpen;render();if(searchOpen){$('#headerSearch details').open=true;$('#search').focus();}});
$('#closeDetail').addEventListener('click',()=>$('#detail').close());$('#detail').addEventListener('close',()=>dialogContext=null);$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close();}});$('#infoButton').addEventListener('click',()=>data&&openDialog({kind:'info'}));
function connection(){const offline=!navigator.onLine;$('#connection').hidden=!offline;$('#connection').textContent='Sin conexión · usando el programa guardado en este dispositivo.';}
window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
async function init(){try{
 const response=await fetch('./agenda.json');if(!response.ok)throw Error('No se pudo cargar el programa.');data=await response.json();try{const profileResponse=await fetch('./speakers.json');if(profileResponse.ok)profiles=(await profileResponse.json()).profiles;}catch{}if(validateData(data).length)throw Error('El programa contiene datos inconsistentes.');lookup={rooms:Object.fromEntries(data.rooms.map(r=>[r.id,r])),blocks:Object.fromEntries(data.blocks.map(b=>[b.id,b])),activities:Object.fromEntries(data.activities.map(a=>[a.id,a]))};const today=eventClock().date;day=data.meta.dates.includes(today)?today:data.meta.dates[0];exploreDate=day;
 let raw=null,legacy=null;try{raw=localStorage.getItem(STORAGE_KEY);legacy=localStorage.getItem('cchr2026-picks-v3');}catch{readOnly=true;showToast('El navegador no permite guardar la ruta; se mantendrá solo durante esta sesión.');}
 const loaded=loadState(raw,data,legacy);state=loaded.state;readOnly=readOnly||loaded.readOnly;render();if(loaded.warnings.length)showToast(loaded.warnings.join(' '));document.body.dataset.ready='true';
 setInterval(()=>{if(!document.hidden&&!exploring&&!$('#detail').open&&document.activeElement?.tagName!=='INPUT')render();},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!exploring&&!$('#detail').open)render();});registerTools();await registerOffline();
 }catch(err){$('#content').innerHTML=empty('No pudimos abrir el programa','Comprueba tu conexión y vuelve a cargar la página. Tus elecciones guardadas no se han borrado.',false)+'<button class="primary" id="retry">Volver a intentar</button>';$('#retry').onclick=()=>location.reload();console.error(err);}}
async function registerOffline(){if(!('serviceWorker'in navigator)||!window.isSecureContext)return;try{const r=await navigator.serviceWorker.register('./sw.js'),show=w=>{waitingWorker=w;$('#update').hidden=false;};if(r.waiting)show(r.waiting);r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)show(w)});});$('#applyUpdate').onclick=()=>{if(save())waitingWorker?.postMessage({type:'ACTIVATE'});};let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(waitingWorker&&!reloading){reloading=true;location.reload();}});}catch{showToast('La agenda funciona, pero no pudo prepararse el uso sin conexión.');}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController(),tools=[{name:'read_congress_route',description:'Leer las actividades elegidas y sus conflictos sin modificar la ruta.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {activities:data.activities.filter(a=>selected(a,state.rules)).map(a=>({id:a.id,title:a.title,date:a.date,start:a.start,end:a.end})),conflicts:conflicts(data.activities,state.rules).pairs};}},{name:'set_congress_activity_selection',description:'Incluir o excluir actividades por ID en la misma ruta local visible, conservando otras elecciones.',inputSchema:{type:'object',properties:{ids:{type:'array',items:{type:'string'},minItems:1,maxItems:100},selected:{type:'boolean'}},required:['ids','selected'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Array.isArray(input.ids)||!input.ids.length||input.ids.length>100||typeof input.selected!=='boolean'||input.ids.some(id=>typeof id!=='string'||!lookup.activities[id]))throw Error('IDs o selección inválidos.');mutate(r=>input.ids.reduce((x,id)=>setRule(x,'activities',id,input.selected),r));return {updated:input.ids.length,selected:input.selected,conflicts:conflicts(data.activities,state.rules).pairs.length};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
init();

